private lemma cast_choose_mul_choose {h a l : ℕ} (hla : l ≤ a) (hah : a ≤ h) :
    (Nat.choose h a : ℝ) * Nat.choose a l =
      Nat.choose h l * Nat.choose (h - l) (a - l)

